'use strict';

var index = require('./index-OWCBTetj.js');

const cardHeadlineCss = () => `:host{pointer-events:none}.card__headline-wrapper{padding-bottom:var(--card-headline-padding, 16px)}.card__headline-wrapper.withDesc{padding-bottom:8px}.card-headline{margin-top:0;padding-top:0;font-family:var(--ifx-font-family);font-weight:600;font-size:1.5rem;line-height:2rem;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;text-overflow:ellipsis}.card-headline.horizontal{font-size:var(--card-headline-font, 1.25rem);line-height:var(--card-headline-line-height, 28px)}`;

const CardHeadline = class {
    constructor(hostRef) {
        index.registerInstance(this, hostRef);
    }
    get el() { return index.getElement(this); }
    direction;
    hasDesc;
    componentWillLoad() {
        const cardElement = this.el.closest("ifx-card");
        if (cardElement) {
            const cardClass = cardElement.shadowRoot.querySelector(".card")?.className;
            if (cardClass && cardClass.includes("horizontal")) {
                this.direction = "horizontal";
            }
            const desc = cardElement.querySelector("ifx-card-text");
            if (desc) {
                this.hasDesc = true;
            }
        }
    }
    render() {
        return (index.h("div", { key: 'e5215de071a90b2ab02b16778f2d44790788a987', class: `card__headline-wrapper ${this.hasDesc ? "withDesc" : ""}` }, index.h("div", { key: '16bc0e82677b301ea459f39310acaa8b270821a6', class: `card-headline ${this.direction}` }, index.h("slot", { key: '8ca8ef57b7360478f8865cbeceff27147801ac3b' }))));
    }
};
CardHeadline.style = cardHeadlineCss();

exports.ifx_card_headline = CardHeadline;
